#!/bin/sh
# Rebuilds the Ghidra project for the game code and regenerates re/work/:
#   decomp.c       decompiled C for every function
#   functions.txt  function index
#   listing.txt    disassembly
#   oracle/        worlds generated by the original code under emulation
# Usage: re/analyze.sh <Populous.adf>      (needs: brew install ghidra)
set -e
cd "$(dirname "$0")/.."
[ -n "$1" ] || { echo "usage: $0 <disk.adf>" >&2; exit 1; }
export JAVA_HOME="${JAVA_HOME:-$(brew --prefix openjdk@21)/libexec/openjdk.jdk/Contents/Home}"
mkdir -p re/work/ghidra
swift run popassets extract "$1" re/work/disk
"$(brew --prefix ghidra)/libexec/support/analyzeHeadless" re/work/ghidra Populous \
    -import re/work/disk/DAD -overwrite \
    -loader BinaryLoader -loader-baseAddr 0x5E7C4 -processor "68000:BE:32:default" \
    -scriptPath re/scripts \
    -postScript PopulousSetup.java \
    -postScript DecompileAll.java re/work/decomp.c re/work/functions.txt \
    -postScript DumpListing.java 0x5E7C4 0x72B9E re/work/listing.txt \
    > re/work/analyze.log 2>&1 || { tail -20 re/work/analyze.log >&2; exit 1; }
# The disk's `populous` program (title picture and demo), flattened at $10000.
# Its A4 is $1ED26; output goes to re/work/intro_decomp.c and intro_listing.txt.
python3 re/flatten_hunks.py re/work/disk/populous re/work/INTRO 10000
"$(brew --prefix ghidra)/libexec/support/analyzeHeadless" re/work/ghidra Populous \
    -import re/work/INTRO -overwrite \
    -loader BinaryLoader -loader-baseAddr 0x10000 -processor "68000:BE:32:default" \
    -scriptPath re/scripts \
    -postScript IntroSetup.java 0x1ed26 \
    -postScript DecompileAll.java re/work/intro_decomp.c re/work/intro_functions.txt \
    -postScript DumpListing.java 0x10000 0x16d28 re/work/intro_listing.txt \
    > re/work/intro_analyze.log 2>&1 || { tail -20 re/work/intro_analyze.log >&2; exit 1; }
# Reference runs of the original code, for Tests/PopulousCoreTests/OracleTests.swift.
# Only the flyer release ($64E46) is skipped; the port does not have it yet.
# This takes tens of minutes: emulation is slow once a world has many people.
emulate() {
    "$(brew --prefix ghidra)/libexec/support/analyzeHeadless" re/work/ghidra Populous \
        -process DAD -noanalysis -readOnly -scriptPath re/scripts \
        -postScript EmulateWorld.java re/work/disk/level.dat re/work/oracle "$@" '!64e46' \
        > re/work/emulate.log 2>&1 || { tail -20 re/work/emulate.log >&2; exit 1; }
}
mkdir -p re/work/oracle
emulate 0,1,2,5,9,10,11,20,30,40,50,60,80,100,150,200,300,400,500,600,700,800,900,1000,1100,1200,1300,1400,1500,1750,2000 0
emulate 0,500,600,700,800,900,1000,1100,1200,1300,1400,1500,1750,2000 5 7
emulate 0,1,50,200,400 '0@a@r10:3,r10:3,r11:4,l7:4,l6:4,l6:4,r40:40,r40:40,r41:40,l0:0,r64:64,l12:5,r9:2,r9:2,r9:2'
emulate 0,1,2,10,50,100,200,300 '0@q@m,q6:1,q6:1,s8:4,v20:20,q3:0' '0@k@m,k' '0@f@m,f' '0@g@m,a'
emulate 0,1,2,5,10,20,30,50,75,100,150,200,300,400,500,600 '825@p@m' '825@n@n'
emulate 1000,1001,1002,1005,1010,1020,1050,1100,1150,1200,1300,1400,1500 '5@x@w1000,m,k' '5@y@w1000,m,a' '5@z@w1000,m,h,k'
grep -E "PopulousSetup.java>" re/work/analyze.log | sed 's/^.*java> //; s/ (GhidraScript).*//'
